import{CITY_LAYOUTS}from'./town-districts.js';
import{readSettlementLibrary}from'./settlement-library.js';
import{townCustomBuildings}from'./town-custom.js';
import{TOWN_PRESETS,FACILITIES,defaultExits,freshTownSeed}from'./town-plan.js';
import{learnTileGrammar}from'./tile-grammar.js';
import{captureNativeAssembly,placeAssembly,removeAssembly,moveAssembly,assemblyCompatibility,refreshPlacedAssemblies}from'./native-assemblies.js';
import{loadRomObjects,readObjectRecipes}from'./rom-objects.js';import{checkMap}from'./map-check.js';import{generateNativeTown,facilityFor}from'./town-generator.js';
export function nativeObjectWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc;let catalogue=null,query='',showAll=false,selected=null;
 const recipes=async()=>catalogue??=await readObjectRecipes();
 const currentProfile=async()=>{const session=api.session();if(!session)throw Error('Open a GBA ROM first.');return(await recipes()).profiles.find(p=>p.sha256===session.id);};
 function preview(reader,o){const n=reader.byKey(o.key),im=reader.render(n),src=document.createElement('canvas');src.width=im.width;src.height=im.height;const ctx=src.getContext('2d'),d=ctx.createImageData(im.width,im.height);d.data.set(im.pixels);ctx.putImageData(d,0,0);const c=document.createElement('canvas');c.width=o.w*16;c.height=o.h*16;for(let y=0;y<o.h;y++)c.getContext('2d').drawImage(src,o.x*16,(o.rows?.[y]??o.y+y)*16,o.w*16,16,0,y*16,o.w*16,16);return c.toDataURL('image/png');}
 async function load(){const s=api.session(),profile=await currentProfile();if(!profile)throw Error('This ROM revision has no reviewed catalogue yet. Import a map and use Extract complete object.');const r=await loadRomObjects(api.project(),s.reader,s.id,profile,api.encodeAtlas);if(api.project().assets.length+r.assets.length>512)throw Error('These objects exceed the project image limit. Use a separate project.');api.change(()=>{api.project().assets.push(...r.assets);api.project().romObjects??=[];for(const t of r.templates){const old=api.project().romObjects.find(p=>p.id===t.id);if(!old)api.project().romObjects.push(t);else Object.assign(old,t);}});await api.loadImages(api.map());api.refresh();api.toast(r.templates.length+' complete source objects available.');return profile;}
 function render(target){target.innerHTML='<div class="toolbox-actions"><button id="loadNativeObjects" type="button">Load objects from this ROM</button><button id="extractNativeObject" type="button">Extract complete object</button><button id="refreshNativeObjects" type="button">Refresh placed object backgrounds</button><button id="checkNativeMap" type="button">Check map</button><button id="createNativeTown" type="button">Create settlement</button></div><p class="hint-line">Complete source tiles with their native layers, collision and elevation. Placed objects are protected from partial edits. Door scripts are added separately.</p><input id="nativeObjectSearch" type="search" aria-label="Find ROM objects" placeholder="House, tree, Centre…"><label class="check"><input id="nativeShowAll" type="checkbox"> Show objects from other tilesets</label><div id="nativeObjectCards" class="toolbox-cards"></div><h3>Placed complete objects</h3><div id="nativePlaced"></div>';
 const cards=()=>{$('#nativeObjectCards').innerHTML=(api.project().romObjects||[]).filter(t=>(showAll||assemblyCompatibility(api.map(),t))&&(t.name+' '+t.category).toLowerCase().includes(query.toLowerCase())).map(t=>`<article class="toolbox-card">${t.preview?`<img class="toolbox-thumb" src="${esc(t.preview)}" alt="${esc(t.name)}">`:''}<b>${esc(t.name)}</b><small>${esc(t.category)} · ${t.w} × ${t.h}</small><button data-native-place="${esc(t.id)}" type="button" ${assemblyCompatibility(api.map(),t)?'':'disabled'}>Place</button>${assemblyCompatibility(api.map(),t)?'':`<small>Different source tileset</small>${t.sourceKey?`<button data-native-source="${esc(t.id)}" type="button">Open matching map</button>`:''}`}</article>`).join('')||'<p class="empty">Load this ROM’s objects, or extract your own. Import a matching source map to place them.</p>';target.querySelectorAll('[data-native-place]').forEach(b=>b.onclick=()=>place((api.project().romObjects||[]).find(t=>t.id===b.dataset.nativePlace)));target.querySelectorAll('[data-native-source]').forEach(b=>b.onclick=()=>api.openSourceMap(api.project().romObjects.find(t=>t.id===b.dataset.nativeSource)).catch(api.error));};
 $('#nativeObjectSearch').value=query;$('#nativeObjectSearch').oninput=e=>{query=e.target.value;cards();};$('#nativeShowAll').checked=showAll;$('#nativeShowAll').onchange=e=>{showAll=e.target.checked;cards();};$('#loadNativeObjects').onclick=()=>load().catch(api.error);$('#extractNativeObject').onclick=extract;$('#refreshNativeObjects').onclick=()=>{try{let n;api.change(()=>{n=refreshPlacedAssemblies(api.project(),api.map());});api.refresh();api.toast(n+' objects refreshed. Changed-size objects need replacing; unlocked edits stay as they are.');}catch(e){api.error(e);}};$('#checkNativeMap').onclick=()=>check().catch(api.error);$('#createNativeTown').onclick=()=>town().catch(api.error);cards();
 $('#nativePlaced').innerHTML=(api.map().nativeAssemblies||[]).map(a=>`<button data-native-edit="${esc(a.id)}" class="connection-item" type="button"><b>${esc(a.name)}</b><span>${a.x}, ${a.y} · ${a.locked?'protected':'unlocked'}</span></button>`).join('')||'<p class="hint-line">Objects placed here stay together.</p>';target.querySelectorAll('[data-native-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.nativeEdit));
 }
 function coords(prefix,x=0,y=0){return`<div class="field-row"><label>Tile X<input id="${prefix}X" type="number" min="0" value="${x}"></label><label>Tile Y<input id="${prefix}Y" type="number" min="0" value="${y}"></label></div>`;}
 function place(t){selected=t;api.placeMode();api.close();api.toast('Tap the top-left tile to place '+t.name+'. The whole object must fit.');}
 function tap(x,y){if(!selected)throw Error('Choose a complete ROM object first.');api.change(()=>placeAssembly(api.project(),api.map(),selected,x,y));api.refresh();}

 function edit(id){const a=api.map().nativeAssemblies.find(a=>a.id===id);api.focus(a.x,a.y);api.modal(a.name,`${coords('nativeMove',a.x,a.y)}<p>${a.w} × ${a.h} tiles. Moving or removing restores the terrain underneath.</p><div class="toolbox-actions"><button id="removeNativeAssembly" type="button">Remove whole object</button><button id="unlockNativeAssembly" type="button">${a.locked?'Unlock individual tiles':'Protect assembly'}</button></div>`,()=>{api.change(()=>moveAssembly(api.project(),api.map(),id,+$('#nativeMoveX').value,+$('#nativeMoveY').value));api.refresh();},'Move object');$('#removeNativeAssembly').onclick=()=>{api.change(()=>{removeAssembly(api.map(),id);api.project().links=api.project().links.filter(l=>l.assemblyId!==id);});api.close();api.refresh();};$('#unlockNativeAssembly').onclick=()=>{api.change(()=>{if(a.locked)a.locked=false;else throw Error('An edited object cannot be protected without saving a new complete template. Extract it again after checking its pieces.');});api.close();api.refresh();};}
 function extract(){api.modal('Extract complete object',`<label>Name<input id="nativeExtractName" maxlength="100" value="My ROM object"></label>${coords('nativeExtract')}<div class="field-row"><label>Width<input id="nativeExtractW" type="number" value="2" min="1" max="64"></label><label>Height<input id="nativeExtractH" type="number" value="3" min="1" max="64"></label></div><p>Include the full crown, trunk, roof and shadow. Forest tiles can contain pieces of neighbouring trees. Review the assembled preview before saving.</p>`,()=>{const t=captureNativeAssembly(api.map(),{x:+$('#nativeExtractX').value,y:+$('#nativeExtractY').value,w:+$('#nativeExtractW').value,h:+$('#nativeExtractH').value},{name:$('#nativeExtractName').value.trim()||'My ROM object',category:'My ROM objects'});showExtract(t).catch(api.error);return false;},'Review object');}
 async function showExtract(t){const c=document.createElement('canvas');c.width=t.w*16;c.height=t.h*16;const ctx=c.getContext('2d'),images=new Map();for(const layer of ['ground','details','objects','overhead'])for(let i=0;i<t.w*t.h;i++){const v=t.layers[layer][i];if(!v)continue;const a=api.project().assets.find(a=>a.id===v.a);if(!a)continue;const im=images.get(a.id)||await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=a.data||a.src;});images.set(a.id,im);ctx.drawImage(im,v.sx,v.sy,v.size,v.size,i%t.w*16,Math.floor(i/t.w)*16,16,16);}t.preview=c.toDataURL('image/png');api.modal('Review '+t.name,`<img class="interior-dialog-preview" src="${esc(t.preview)}" alt="Full extracted object"><p>Check every edge for missing foliage, roofs, shadows or neighbouring objects. Collision and native layers are included.</p><label class="check"><input id="nativeConfirmComplete" type="checkbox"> The object is complete and has no cut-off neighbouring parts</label>`,()=>{if(!$('#nativeConfirmComplete').checked)throw Error('Review the complete object before saving it.');api.change(()=>{api.project().romObjects??=[];if(api.project().romObjects.length>=512)throw Error('This project has 512 ROM objects.');api.project().romObjects.push(t);});api.refresh();},'Save complete object');}
 async function check(){const session=api.session(),map=api.map(),native=session?.id===map.rom?.sourceId?session.reader.byKey(map.rom.key||map.rom.templateKey):null,grammar=native?await learnTileGrammar(session.reader,native):null;if(api.map()!==map)return;const f=checkMap(api.project(),map,{grammar});api.modal('Map check',`<p>${f.filter(f=>f.severity==='error').length} errors · ${f.filter(f=>f.severity==='warning').length} things to review. Unusual tile joins are learned from source maps and need visual review. Reachability checks assume ordinary walking; playtest ledges, Surf and quest gates.</p>${f.map((f,i)=>`<button type="button" data-map-finding="${i}" class="connection-item"><b>${esc(f.severity)} · ${f.x}, ${f.y}</b><span>${esc(f.message)}</span></button>`).join('')||'<p>No structural issues found by these checks. Review the map visually and playtest its routes.</p>'}`);document.querySelectorAll('[data-map-finding]').forEach(b=>b.onclick=()=>{const v=f[+b.dataset.mapFinding];api.close();api.focus(v.x,v.y);});}
 async function town(){const included=await readSettlementLibrary(),opened=api.session(),profile=included.profiles.find(p=>opened&&p.sha256===opened.id)||included.profiles.find(p=>p.id==='firered'),custom=await townCustomBuildings(api.project(),opened?.reader.metatileLayers||2,api.encodeAtlas);let exits=defaultExits(2),active=0;const sources=included.profiles.map(t=>({id:t.id,label:t.name,ready:true}));
 api.modal('Create settlement',`<label>Name<input id="nativeTownName" maxlength="100" value="New town"></label><label>Terrain style<select id="townTerrainStyle">${included.profiles.filter(t=>t.terrain).map(t=>`<option value="${t.id}" ${t.id===profile.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Preset<select id="nativeTownTheme">${TOWN_PRESETS.map(t=>`<option value="${t.id}" ${t.id==='meadow-town'?'selected':''}>${t.name}</option>`).join('')}</select></label><label>City layout<select id="nativeTownLayout"><option value="auto">Auto · change with seed</option>${CITY_LAYOUTS.map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select></label><p class="hint-line" id="townLayoutNote">Available for coastal, city and metro presets. Layouts use district and street rules inspired by these cities, with new building arrangements.</p><div class="field-row"><label>Seed<input id="nativeTownSeed" type="number" value="${freshTownSeed()}"></label><button id="newTownSeed" type="button">New layout seed</button></div><fieldset><legend>Building sources</legend>${sources.map(t=>`<label class="check"><input type="checkbox" data-town-style="${t.id}" ${t.id===profile.id?'checked':''} >${esc(t.label)}</label>`).join('')}<p class="hint-line">All sources are included and work offline. Select any combination. Other includes Ekat and Apathy art packs, bundled Kanto / Johto / Hoenn buildings, and My library. GBA export still needs palette review.</p></fieldset><fieldset><legend>Facilities</legend>${FACILITIES.map(([id,label])=>`<label class="check"><input type="checkbox" data-town-facility="${id}" ${['centre','mart','gym'].includes(id)?'checked':''}>${label}</label>`).join('')}<p id="townFacilityNote" class="hint-line"></p></fieldset><fieldset><legend>Extra features</legend><label class="check"><input id="townFeatureTrees" type="checkbox" checked> Trees and planting</label><label class="check"><input id="townFeatureFences" type="checkbox" checked> Fences and garden boundaries</label><label class="check"><input id="townFeatureParks" type="checkbox" checked> Park lots (cities / metro)</label><label class="check"><input id="townFeatureFlowers" type="checkbox" checked> Flower clumps (when available)</label><label class="check"><input id="townFeatureRocks" type="checkbox" checked> Cave boulders (underground)</label><label class="check"><input id="townFeatureWater" type="checkbox"> Waterfront / pond</label></fieldset><fieldset><legend>Town exits</legend><label>Number of exits<select id="townExitCount">${Array.from({length:9},(_,i)=>`<option value="${i}" ${i===2?'selected':''}>${i}</option>`).join('')}</select></label><p class="hint-line">Select an exit and tap an edge. Openings are three tiles wide; link them in World after generation.</p><svg id="townExitPlan" viewBox="0 0 320 230" role="img" aria-label="Town boundary and exit positions" style="width:100%;height:auto;aspect-ratio:320/230;display:block;max-width:420px;touch-action:none"></svg><div id="townExitRows"></div></fieldset><label class="check"><input id="nativeTownInteriors" type="checkbox" checked> Create and link available interiors</label><p class="hint-line">Coastal settlements have harbour districts, a shaped shoreline, promenades and masonry piers. Cities group buildings around local streets, shopping areas, gardens and a central square. Choose a layout or let the seed pick one. Creates a separate editable map. Underground uses native cave walls, chambers and pillars. Interiors use included room artwork; source story scripts are removed. Department stores get matching floors, stairs and all front doors. Lifts use a stair-access notice. Game corners and store clerks still need their gameplay events.</p>`,async()=>{const session=api.session(),styles=[...document.querySelectorAll('[data-town-style]:checked')].map(e=>e.dataset.townStyle),facilities=[...document.querySelectorAll('[data-town-facility]:checked')].map(e=>e.dataset.townFacility),result=await generateNativeTown(api.project(),session?.reader,session?.id,included.profiles.find(p=>p.id===$('#townTerrainStyle').value),{name:$('#nativeTownName').value.trim()||'New town',preset:$('#nativeTownTheme').value,layout:$('#nativeTownLayout').value,seed:+$('#nativeTownSeed').value,styles,facilities,exits:structuredClone(exits),features:{fences:$('#townFeatureFences').checked,parks:$('#townFeatureParks').checked,trees:$('#townFeatureTrees').checked,flowers:$('#townFeatureFlowers').checked,rocks:$('#townFeatureRocks').checked,water:$('#townFeatureWater').checked},additionalTemplates:styles.includes('other')?custom.templates:[],additionalAssets:styles.includes('other')?custom.assets:[],interiors:$('#nativeTownInteriors').checked,encodeAtlas:api.encodeAtlas});api.change(()=>{api.project().assets.push(...result.assets.filter(a=>!api.project().assets.some(b=>b.id===a.id)));api.project().maps.push(...result.maps);api.project().links.push(...result.links);api.project().romObjects??=[];for(const t of result.templates){const old=api.project().romObjects.find(p=>p.id===t.id);if(old)Object.assign(old,t);else api.project().romObjects.push(t);}});api.close();api.loadMap(result.maps[0].id);api.refresh();api.toast(result.maps.length+' maps created. '+result.maps[0].generator.missingInteriors+' buildings need interior links.');return false;},'Generate settlement');
 $('#newTownSeed').onclick=()=>{$('#nativeTownSeed').value=freshTownSeed();};const updateLayout=()=>{const preset=$('#nativeTownTheme').value,coast=preset.startsWith('coastal-'),enabled=coast||preset.startsWith('metro-')||preset.endsWith('-city')&&!preset.startsWith('underground-');$('#nativeTownLayout').disabled=!enabled;for(const o of $('#nativeTownLayout').options){const l=CITY_LAYOUTS.find(l=>l.id===o.value);o.disabled=coast&&l&&!l.coastal;}if($('#nativeTownLayout').selectedOptions[0]?.disabled)$('#nativeTownLayout').value='auto';};$('#nativeTownTheme').onchange=()=>{$('#townFeatureWater').checked=/^(coastal|lakeside)-/.test($('#nativeTownTheme').value);updateLayout();};updateLayout();
 function sourcesChanged(){const selected=[...document.querySelectorAll('[data-town-style]:checked')].map(e=>e.dataset.townStyle),pool=included.templates.filter(t=>selected.includes(t.profileId)),available=new Set(pool.map(t=>t.kind)),fallbacks=FACILITIES.filter(([id])=>!available.has(id)).map(([,label])=>label);$('#townFacilityNote').textContent=fallbacks.length?'Included fallback artwork: '+fallbacks.join(', ')+'.':'All facilities are available in the selected styles.';}document.querySelectorAll('[data-town-style]').forEach(e=>e.onchange=sourcesChanged);sourcesChanged();
 function renderExits(){const svg=$('#townExitPlan');svg.innerHTML='<rect x="30" y="25" width="260" height="180" rx="4" fill="#344637" stroke="#93ad73" stroke-width="8"/><text x="160" y="110" fill="#e5edc9" text-anchor="middle" font-size="14">Town boundary</text><text x="160" y="130" fill="#e5edc9" text-anchor="middle" font-size="11">Select an exit, then tap an edge</text>'+exits.map((e,i)=>{const x=['north','south'].includes(e.edge)?30+260*e.position/100:e.edge==='west'?30:290,y=['east','west'].includes(e.edge)?25+180*e.position/100:e.edge==='north'?25:205;return`<g data-exit-dot="${i}" tabindex="0" role="button" aria-label="Select exit ${i+1}"><circle cx="${x}" cy="${y}" r="12" fill="${i===active?'#f3c66c':'#a7d4c9'}" stroke="#17231e" stroke-width="2"/><text x="${x}" y="${y+4}" font-size="12" fill="#17231e" text-anchor="middle">${i+1}</text></g>`;}).join('');$('#townExitRows').innerHTML=exits.map((e,i)=>`<div class="field-row"><label>Exit ${i+1}<select data-exit-edge="${i}">${['north','east','south','west'].map(v=>`<option ${v===e.edge?'selected':''}>${v}</option>`).join('')}</select></label><label>Position · <span id="exitPercent${i}">${e.position}%</span><input data-exit-position="${i}" aria-label="Exit ${i+1} position" type="range" min="5" max="95" value="${e.position}"></label></div>`).join('');svg.querySelectorAll('[data-exit-dot]').forEach(e=>{const select=ev=>{ev.stopPropagation();active=+e.dataset.exitDot;renderExits();};e.onclick=select;e.onkeydown=ev=>{if(['Enter',' '].includes(ev.key))select(ev);};});document.querySelectorAll('[data-exit-edge]').forEach(e=>e.onchange=()=>{active=+e.dataset.exitEdge;exits[active].edge=e.value;renderExits();});document.querySelectorAll('[data-exit-position]').forEach(e=>{e.oninput=()=>{active=+e.dataset.exitPosition;exits[active].position=+e.value;$('#exitPercent'+active).textContent=e.value+'%';};e.onchange=renderExits;});}
 $('#townExitCount').onchange=e=>{const n=+e.target.value;exits=Array.from({length:n},(_,i)=>exits[i]||defaultExits(n)[i]);active=Math.min(active,n-1);renderExits();};$('#townExitPlan').onclick=e=>{if(active<0||!exits.length)return;const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*320,y=(e.clientY-r.top)/r.height*230,edge=[['west',Math.abs(x-30)],['east',Math.abs(x-290)],['north',Math.abs(y-25)],['south',Math.abs(y-205)]].sort((a,b)=>a[1]-b[1])[0][0];exits[active]={edge,position:Math.max(5,Math.min(95,Math.round((['west','east'].includes(edge)?(y-25)/180:(x-30)/260)*100)))};renderExits();};renderExits();
 }

 return{render,load,extract,check,town,tap,edit,get selected(){return selected;}};
}
